  const VALID_IAU_SET = new Set(Object.keys(IAU_PATTERNS));

  function hydrateCatalog(rawCurricula) {
    const out = {};
    const src = rawCurricula || COMPACT_CURRICULA;
    if (!src || typeof src !== 'object') return out;
    Object.keys(src).forEach(function (galId) {
      const chapters = src[galId];
      if (!Array.isArray(chapters)) return;
      out[galId] = chapters.map(function (chEntry, cIdx) {
        if (!Array.isArray(chEntry)) return null;
        const iauRaw = String(chEntry[0] || 'Orion');
        const iau = VALID_IAU_SET.has(iauRaw) ? iauRaw : 'Orion';
        const chTitle = String(chEntry[1] || ('Chương ' + (cIdx + 1)));
        const rawStars = Array.isArray(chEntry[2]) ? chEntry[2] : [];
        const stars = rawStars.map(function (stEntry, sIdx) {
          if (!Array.isArray(stEntry)) return null;
          const stTitle = String(stEntry[0] || ('Bài ' + (sIdx + 1)));
          const spec = String(stEntry[1] || 'G');
          const rawPlanets = Array.isArray(stEntry[2])
            ? stEntry[2]
            : (typeof stEntry[2] === 'string' && stEntry[2].trim()
                ? stEntry[2].split('|').map(function (s) { return s.trim(); }).filter(Boolean)
                : ['Nội dung trọng tâm']);
          return [stTitle, spec, rawPlanets];
        }).filter(Boolean);
        return [iau, chTitle, stars];
      }).filter(Boolean);
    });
    return out;
  }

